#[summary("impossibility certificate")]
mod bmb_cert {
    spec fn never() -> bool { false }

    spec fn witness(w: u64, h: u64) -> bool { w == 5000000000 && h == 5000000000 }

    #[effects(pure)]
    #[uses(witness, tasks::side_ok, tasks::is_area)]
    fn refute(w: u64, h: u64) -> ()
        requires witness(w, h),
        ensures never(),
    {
        let r: u64 = tasks::area(w, h);
    }

    #[effects(pure)]
    #[uses(witness)]
    fn reach() -> () {
        refute(5000000000, 5000000000)
    }
}

